#[derive(Clone, PartialEq)]
struct DocState { text: String, caret: usize }

struct Editor { state: DocState, history: Vec<DocState> }   // caretaker

impl Editor {
    fn save(&mut self) { self.history.push(self.state.clone()); }
    fn undo(&mut self) {
        if let Some(previous) = self.history.pop() { self.state = previous; }
    }
}

