#[derive(Serialize, Deserialize, PartialEq)]
struct DocState { text: String, caret: usize }

fn snapshot(state: &DocState) -> String {
    serde_json::to_string(state).expect("state is serializable")
}

fn restore(blob: &str) -> DocState {
    serde_json::from_str(blob).expect("snapshot came from this version")
}
